import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.clip(x, -5, 5)
    n = len(x)

    quadratic_term = np.sum(x**2)
    interaction_term = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            interaction_term += x[i] * x[j]

    skewness_term = np.exp(0.1 * x[0])

    frequency_term = np.sum(np.cos(x) * np.arange(1, n + 1)) * 0.1

    result = 0.7 * quadratic_term + 0.2 * interaction_term + 0.05 * skewness_term + frequency_term + 0.01 * np.sum(x)

    return float(result)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    x_scaled = (x + 5) / 10
    l1_norm = np.sum(np.abs(x_scaled))
    skewed_power = (l1_norm**1.5) * np.exp(2 * l1_norm)
    interaction = 0.0
    for i in range(5):
        for j in range(i + 1, 5):
            interaction += x_scaled[i] * x_scaled[j]
    result = 0.6 * skewed_power + 0.2 * interaction
    scaling_factor = 0.005
    return float(scaling_factor * result)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    x_scaled = (x + 5) / 10
    l1_norm = np.sum(np.abs(x_scaled))
    skewed_power = (l1_norm**1.5) * np.exp(2 * l1_norm)
    interaction = 0.0
    for i in range(5):
        for j in range(i + 1, 5):
            interaction += x_scaled[i] * x_scaled[j]
    sinusoidal_component = 0.0
    for i in range(5):
        sinusoidal_component += np.sin(2 * np.pi * (i + 1) * x_scaled[i])
    result = 0.6 * skewed_power + 0.2 * interaction + 0.15 * sinusoidal_component
    scaling_factor = 0.005
    return float(scaling_factor * result)
